public class PolymorphismDemo {
    // Compile-time polymorphism (Overloading)
    public double calculateTax(double amount) {
        return amount * 0.05;
    }

    public double calculateTax(double amount, double surcharge) {
        return (amount * 0.05) + surcharge;
    }

    public static void main(String[] args) {
        PolymorphismDemo demo = new PolymorphismDemo();
        System.out.println(demo.calculateTax(100.0));       // Resolves to 1-arg
        System.out.println(demo.calculateTax(100.0, 10.0)); // Resolves to 2-arg

        // Runtime polymorphism (Overriding & Dynamic Dispatch)
        Notification channel = new EmailNotification();
        channel.send("System Alert: CPU spike detected"); // Executes EmailNotification's send()
    }
}

interface Notification {
    void send(String message);
}

class EmailNotification implements Notification {
    @Override
    public void send(String message) {
        System.out.println("Sending Email: " + message);
    }
}
